  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  updated_at                   timestamptz NOT NULL DEFAULT now(),
  updated_by                   varchar(64),
  row_version                  integer NOT NULL DEFAULT 1,
  product_id                   uuid,
  segment                      varchar(64),
  currency                     char(3),
  method                       varchar(40) NOT NULL CHECK (method IN ('MATCHED_MATURITY', 'POOLED', 'BEHAVIOURAL', 'FIXED_SPREAD')),
  base_curve_code              varchar(32) NOT NULL,
  liquidity_curve_code         varchar(32),
  fixed_spread                 numeric(18,10),
  pool_tenor_days              integer,
  priority                     integer NOT NULL DEFAULT 100,
  valid_from                   date NOT NULL,
  valid_to                     date,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500)
);
COMMENT ON TABLE ftp_rule IS 'Rule assigning an FTP method and curves to products / segments';
COMMENT ON COLUMN ftp_rule.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN ftp_rule.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN ftp_rule.created_at IS 'Creation time';
COMMENT ON COLUMN ftp_rule.created_by IS 'Principal that created the row';
COMMENT ON COLUMN ftp_rule.updated_at IS 'Last update time';
COMMENT ON COLUMN ftp_rule.updated_by IS 'Principal that last updated the row';
COMMENT ON COLUMN ftp_rule.row_version IS 'Optimistic lock version; send as If-Match';
COMMENT ON COLUMN ftp_rule.product_id IS 'Product (empty = default)';
COMMENT ON COLUMN ftp_rule.segment IS 'Segment';
COMMENT ON COLUMN ftp_rule.currency IS 'Currency';
COMMENT ON COLUMN ftp_rule.method IS 'Pricing method';
COMMENT ON COLUMN ftp_rule.base_curve_code IS 'Base curve code';
COMMENT ON COLUMN ftp_rule.liquidity_curve_code IS 'Liquidity premium curve code';
COMMENT ON COLUMN ftp_rule.fixed_spread IS 'Spread for FIXED_SPREAD method';
COMMENT ON COLUMN ftp_rule.pool_tenor_days IS 'Pricing tenor for POOLED (default 30)';
COMMENT ON COLUMN ftp_rule.priority IS 'Lower wins';
COMMENT ON COLUMN ftp_rule.valid_from IS 'Effective from';
COMMENT ON COLUMN ftp_rule.valid_to IS 'Effective to';
COMMENT ON COLUMN ftp_rule.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_rule.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_rule.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_rule.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_rule.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_ftp_rule_tenant ON ftp_rule (tenant_id, created_at);
CREATE INDEX ix_ftp_rule_product_id ON ftp_rule (product_id);
ALTER TABLE ftp_rule ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ftp_rule USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_ftp_rule_touch BEFORE UPDATE ON ftp_rule FOR EACH ROW EXECUTE FUNCTION touch_row();

-- ftp_assignment: FTP rate and margin assigned to an account or loan for a period
CREATE TABLE ftp_assignment (
  id                           uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id                    uuid NOT NULL,
  created_at                   timestamptz NOT NULL DEFAULT now(),
  created_by                   varchar(64),
  period_start                 date NOT NULL,
  period_end                   date NOT NULL,
  exposure_type                varchar(40) NOT NULL CHECK (exposure_type IN ('DEPOSIT_ACCOUNT', 'TERM_DEPOSIT', 'LOAN', 'CREDIT_LINE')),
  exposure_id                  uuid NOT NULL,
  deposit_account_id           uuid,
  loan_id                      uuid,
  product_id                   uuid,
  ftp_rule_id                  uuid REFERENCES ftp_rule(id),
  term_days                    integer,
  average_balance              numeric(28,8) NOT NULL,
  currency                     char(3) NOT NULL,
  customer_rate                numeric(18,10) NOT NULL,
  ftp_rate                     numeric(18,10) NOT NULL,
  net_margin                   numeric(18,10) NOT NULL,
  ftp_charge_credit            numeric(28,8) NOT NULL,
  custom_field_1               varchar(500),
  custom_field_2               varchar(500),
  custom_field_3               varchar(500),
  custom_field_4               varchar(500),
  custom_field_5               varchar(500),
  CONSTRAINT uq_ftp_assignment_1 UNIQUE (tenant_id, exposure_id, period_start)
);
COMMENT ON TABLE ftp_assignment IS 'FTP rate and margin assigned to an account or loan for a period';
COMMENT ON COLUMN ftp_assignment.id IS 'Unique id (UUIDv7, time-ordered)';
COMMENT ON COLUMN ftp_assignment.tenant_id IS 'Owning tenant; enforced by row-level security';
COMMENT ON COLUMN ftp_assignment.created_at IS 'Creation time';
COMMENT ON COLUMN ftp_assignment.created_by IS 'Principal that created the row';
COMMENT ON COLUMN ftp_assignment.period_start IS 'Period start';
COMMENT ON COLUMN ftp_assignment.period_end IS 'Period end';
COMMENT ON COLUMN ftp_assignment.exposure_type IS 'Deposit account, term deposit, loan or credit line';
COMMENT ON COLUMN ftp_assignment.exposure_id IS 'Account or loan id';
COMMENT ON COLUMN ftp_assignment.deposit_account_id IS 'Deposit account, when applicable';
COMMENT ON COLUMN ftp_assignment.loan_id IS 'Loan, when applicable';
COMMENT ON COLUMN ftp_assignment.product_id IS 'Product';
COMMENT ON COLUMN ftp_assignment.ftp_rule_id IS 'Rule applied';
COMMENT ON COLUMN ftp_assignment.term_days IS 'Pricing tenor used';
COMMENT ON COLUMN ftp_assignment.average_balance IS 'Average balance for the period';
COMMENT ON COLUMN ftp_assignment.currency IS 'Currency';
COMMENT ON COLUMN ftp_assignment.customer_rate IS 'Rate paid / earned with the customer';
COMMENT ON COLUMN ftp_assignment.ftp_rate IS 'Transfer price';
COMMENT ON COLUMN ftp_assignment.net_margin IS 'Customer rate minus FTP for assets, FTP minus customer rate for liabilities';
COMMENT ON COLUMN ftp_assignment.ftp_charge_credit IS 'FTP charge (loans) or credit (deposits) for the period (ACT/365)';
COMMENT ON COLUMN ftp_assignment.custom_field_1 IS 'Tenant-defined custom field 1; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_assignment.custom_field_2 IS 'Tenant-defined custom field 2; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_assignment.custom_field_3 IS 'Tenant-defined custom field 3; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_assignment.custom_field_4 IS 'Tenant-defined custom field 4; label, type and validation configured in custom_field_definition';
COMMENT ON COLUMN ftp_assignment.custom_field_5 IS 'Tenant-defined custom field 5; label, type and validation configured in custom_field_definition';
CREATE INDEX ix_ftp_assignment_tenant ON ftp_assignment (tenant_id, created_at);
CREATE INDEX ix_ftp_assignment_exposure_id ON ftp_assignment (exposure_id);
CREATE INDEX ix_ftp_assignment_deposit_account_id ON ftp_assignment (deposit_account_id);
CREATE INDEX ix_ftp_assignment_loan_id ON ftp_assignment (loan_id);
CREATE INDEX ix_ftp_assignment_product_id ON ftp_assignment (product_id);
CREATE INDEX ix_ftp_assignment_ftp_rule_id ON ftp_assignment (ftp_rule_id);
ALTER TABLE ftp_assignment ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON ftp_assignment USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE TRIGGER trg_ftp_assignment_append_only BEFORE UPDATE OR DELETE ON ftp_assignment FOR EACH ROW EXECUTE FUNCTION forbid_mutation();

-- Transactional outbox: events are written here in the same transaction as the
-- state change and relayed to Kafka by the outbox relay (Debezium).
CREATE TABLE outbox (
  id              uuid PRIMARY KEY DEFAULT uuidv7(),
  tenant_id       uuid NOT NULL,
  aggregate_type  varchar(64) NOT NULL,
  aggregate_id    uuid NOT NULL,
  event_type      varchar(128) NOT NULL,
  payload         jsonb NOT NULL,
  headers         jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_outbox_created ON outbox (created_at);

-- Idempotency keys for POST requests (24h retention).
CREATE TABLE idempotency_key (
  tenant_id       uuid NOT NULL,
  key             varchar(128) NOT NULL,
  request_hash    varchar(64) NOT NULL,
  response_status integer,
  response_body   jsonb,
  created_at      timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, key)
);

-- Runtime access for the non-superuser application role (RLS does not apply to superusers).
DO $$
BEGIN
  IF EXISTS (SELECT FROM pg_roles WHERE rolname = 'meridian_app') THEN
    GRANT USAGE ON SCHEMA alm TO meridian_app;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA alm TO meridian_app;
    ALTER DEFAULT PRIVILEGES IN SCHEMA alm GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO meridian_app;
  END IF;
END $$;
